Since all the characters in $S$ are primitive, any distinct $\chi_1, \chi_2 \in S$ must induce different characters modulo $re$. Thus $\chi_1 \overline{\chi_2} \mathbbm{1}_{(re, \cdot) = 1}$ is not the principal character modulo $re$, so it must have average $0$. But then
\[
\begin{aligned}
    &\sum_{\substack{b \in (\mathbf{Z}/re\mathbf{Z})^\times}} \left\vert \sum_{(k,re)=1} u_k \left(\omega_\infty(k\overline{b}; re) - \omega_D(k\overline{b}; r) \right)\right\vert^2
    \\
    &=
    \sum_{\substack{b \in (\mathbf{Z}/re\mathbf{Z})^\times}} \left\vert \sum_{\chi \in S} \overline{\chi}(b) \sum_{(k,re)=1} u_k \chi(k) \right\vert^2
    \\
    &=
    \sum_{\chi_1,\chi_2 \in S} \left(\sum_{(k,re)=1} u_k \chi_1(k)\right)\overline{\left(\sum_{(k,re)=1} u_k \chi_2(k)\right)} \sum_{\substack{b \in (\mathbf{Z}/re\mathbf{Z})^\times}} \overline{\chi_1}(b) \chi_2(b) 
    \\
    &=
    \varphi(re) \sum_{\chi \in S} \left\vert \sum_{(k,re)=1} u_k \chi(k)\right\vert^2.
\end{aligned}    
\]
We conclude that
\[
\begin{aligned}
    X_1 - 2\textnormal{Re} X_2 + X_3 
    \ &\ll  
    \frac{1}{R}\sum_{e \in \mathscr{E}} \sum_r \Phi\left(\frac{r}{R}\right) \frac{1}{\varphi(re)}  \sum_{\chi \in S} \left\vert \sum_{(k,re)=1} u_k \chi(k)\right\vert^2
    \\
    &\le
    \frac{1}{R}\sum_{e \in \mathscr{E}} \sum_r \Phi\left(\frac{r}{R}\right) \frac{1}{\varphi(re)}  \sum_{\substack{\chi \text{ primitive} \\ \textnormal{cond}(\chi) > D \\ \textnormal{cond}(\chi) \mid re}} \left\vert \sum_{(k,re)=1} u_k \chi(k)\right\vert^2,
\end{aligned}
\]
where we used that all characters $\chi \in S_1$ also have $\textnormal{cond}(\chi) > D$, since $D \le x^\varepsilon < E \le e \mid \textnormal{cond}(\chi)$. Now letting $Q := RE$, substituting $q$ for $re$, and using that $q$ has $O(\log q)$ different prime factors, we can bound the sum above by 
\[
\begin{aligned}
    X_1 - 2\textnormal{Re} X_2 + X_3 
    &\ll
    \frac{\log x}{R}\sum_{Q/2 \le q \le 6Q} \frac{1}{\varphi(q)} \sum_{\substack{\chi \text{ primitive} \\ \textnormal{cond}(\chi) > D \\ \textnormal{cond}(\chi) \mid q}} \left\vert \sum_{(k,q)=1} u_k \chi(k)\right\vert^2.
    \\
    &\le
    \frac{\log x}{R}
    \sum_{D < s \le 6Q}
    \sum_{\substack{\chi \text{ primitive} \\ \textnormal{cond}(\chi) = s}}\,
    \sum_{\substack{q \le 6Q \\ s \mid q}}
    \frac{1}{\varphi(q)} \left\vert \sum_{(k,q/s)=1} u_k \chi(k)\right\vert^2
    \\
    &\le 
    \frac{\log x}{R}
    \sum_{D < s \le 6Q}
    \sum_{\substack{\chi \text{ primitive} \\ \textnormal{cond}(\chi) = s}}\,
    \sum_{\substack{q \le 6Q \\ s \mid q}}
    \frac{\tau(q/s)}{\varphi(q)} 
    \sum_{d \mid q/s} \left\vert \sum_{k'} u_{dk'} \chi(dk')\right\vert^2
    \\
    &\le
    \frac{\log x}{R}
    \sum_{d \le 6Q}
    \sum_{D < s \le 6Q}
    \sum_{\substack{\chi \text{ primitive} \\ \textnormal{cond}(\chi) = s}}\,
    \left\vert \sum_{k'} u_{dk'} \chi(k')\right\vert^2 
    \sum_{\substack{q \le 6Q \\ ds \mid q}}
    \frac{\tau(q/s)}{\varphi(q)},
\end{aligned}
\]
where we decomposed $\mathbbm{1}_{(a, b) = 1} = \sum_{d \mid (a, b)} \mu(d)$ to get rid of the coprimality restriction. Noting that
\[
    \sum_{\substack{q \le 6Q \\ sd \mid q}}
    \frac{\tau(q/s)}{\varphi(q)}
    \le
    \sum_{\substack{q' \le 6Q}}
    \frac{\tau(q'd)}{\varphi(q'ds)}
    \le 
    \frac{\tau(d)}{\varphi(d)\varphi(s)}
    \sum_{\substack{q' \le 6Q}}
    \frac{\tau(q')}{\varphi(q')}
