\end{aligned}
\]
\[
\begin{aligned}
    \mathcal{B}_{\neq} &:=
    \sum_{t \sim T} \sum_{e_0 \sim E_0}\,
    \sum_{\substack{e_1', e_2' \sim E/e_0 \\ (e_1', e_2') = 1}}
    \sum_{\substack{s \sim S \\ s \mid te_0 \\ (s, e_1'e_2'b) = 1}}
    \sum_{\substack{\ell_1, \ell_2 \sim L \\ \ell_1 \equiv \ell_2 \pmod{te_0} \\ (\ell_1 \ell_2, te_0) = 1 \\ (\ell_1, e_1') = (\ell_2, e_2') = 1 \\ \ell_1 \neq \ell_2}} 
