This is essentially the same as the proof of \cite[Lemma 18.5]{maynard2020primes}, but in a slightly more general setting (the main difference being the additional parameters $b, d$). 
We first replace the indicator functions of $k \sim K$ and $n \sim N$ with smooth majorants, using a suitable smooth compactly supported function $f_0$ (we choose this as in the proof of \cite[Lemma 18.5]{maynard2020primes}). Expanding out the square in $\mathcal{B}$ and swapping sums, we then obtain
\begin{equation} \label{eq:b-estimate}
\begin{aligned}
    \mathcal{B} &\le 
    \sum_{\substack{k \\ (k, b) = 1}} f_0\left(\frac{k}{K}\right)
    \sum_{\substack{n \\ (n, k) = 1}} f_0\left(\frac{n}{N}\right) 
    \sum_{\substack{t \sim T \\ (t, dk) = 1}} t \left\vert
    \sum_{\substack{e \sim E \\ (e, dk) = 1}}
    \sum_{h \sim H} 
    \sum_{\substack{\ell \sim L \\ (\ell, ket) = 1 \\ n \ell \equiv d k \pmod{et}}} 
    \beta(e, h, \ell)\ \textnormal{e}\left(het \frac{\overline{b n \ell}}{k}\right)
    \right\vert^2
    \\
    &=
    \sum_{\substack{t \sim T \\ (t, d) = 1}} t 
    \sum_{\substack{e_1, e_2 \sim E \\ (e_1 e_2, d) = 1}}\ 
    \sum_{\substack{\ell_1, \ell_2 \sim L \\ \ell_1 \equiv \ell_2 \pmod{t(e_1, e_2)} \\ (\ell_1, te_1) = 1 \\ (\ell_2, te_2) = 1}}
    \sum_{h_1, h_2 \sim H} \beta(e_1, h_1, \ell_1) \, \overline{\beta(e_2, h_2, \ell_2)} 
    \\
    &\qquad\qquad \times 
    \sum_{\substack{k \\ (k, te_1e_2\ell_1\ell_2b) = 1}} 
    f_0\left(\frac{k}{K}\right)
    \sum_{\substack{(n, k) = 1 \\ n \equiv dk\overline{\ell_1} \pmod{te_1} \\ n \equiv dk\overline{\ell_2} \pmod{te_2}}}
    f_0\left(\frac{n}{N}\right)
    \textnormal{e} \left(t\frac{(h_1e_1\ell_2 - h_2e_2\ell_1)\overline{bn \ell_1 \ell_2}}{k} \right),
\end{aligned}
\end{equation}
where we used that $(n, et) = 1$ to deduce the congruence between $\ell_1$ and $\ell_2$ (indeed, if a prime $p$ divided both $n$ and $et$, then it would divide $dk$, but $(et, dk) = 1$).

Let $\mathcal{B}_1$ denote the contribution of the `diagonal' terms with $h_1 e_1 \ell_2 = h_2 e_2 \ell_1$, and $\mathcal{B}_2$ contain the other terms; thus we have $\mathcal{B} \le \mathcal{B}_1 + \mathcal{B}_2$. We first bound $\mathcal{B}_1$ trivially (using the divisor bound) by
\begin{equation} \label{eq:b1-estimate}
\begin{aligned}
    \mathcal{B}_1 &\ll 
    \sum_{\substack{t \sim T \\ (t, d) = 1}} t 
    \sum_{\substack{e_1 \sim E \\ \ell_2 \sim L \\ h_1 \sim H}}
    \,
    \sum_{\substack{e_2 \sim E \\ \ell_1 \sim L \\ e_2\ell_1 \mid h_1e_1\ell_2 \\ \ell_1 \equiv \ell_2 \pmod{t(e_1,e_2)} \\ (\ell_1, te_1) = (\ell_2, te_2) = 1}}
    \sum_{\substack{h_2 \sim H \\ h_1e_1\ell_2 = h_2e_2\ell_1}}
    \sum_k 
    f_0\left(\frac{k}{K}\right)
    \sum_{\substack{n \equiv dk\overline{\ell_1} \pmod{te_1} \\ n \equiv dk\overline{\ell_2} \pmod{te_2}}}
    f_0\left(\frac{n}{N}\right)
    \\
    &\ll 
    \sum_{t \sim T} t 
    \sum_{\substack{e_1 \sim E \\ \ell_2 \sim L \\ h_1 \sim H}}
    \,
    \sum_{\substack{e_2 \sim E,\ \ell_1 \sim L \\ h_2 \sim H \\ h_1e_1\ell_2 = h_2e_2\ell_1  \\ (\ell_1, te_1) = 1}}
    \sum_{k \ll K} 
    \sum_{\substack{n \ll N \\ n \equiv dk\overline{\ell_1} \pmod{te_1}}}
    1
    \\
    &\ll_\eta x^{O(\eta)}\, 
    T^2 ELHK \left(\frac{N}{TE} + 1\right),
\end{aligned}
\end{equation}
recovering the first two terms in the desired bound. Next, we consider $\mathcal{B}_2$, containing the terms with $h_1 e_1 \ell_2 \neq h_2 e_2 \ell_1$. We let $e_0 := (e_1, e_2)$, $e_1' := e_1/e_0$ and $e_2' := e_2/e_0$ and put $e_0$ in dyadic ranges $e_0 \sim E_0$ to write 
\[
\begin{aligned}
