    \\
    &\times \sup_{E_0 \ll E} \bigg\vert 
    \sum_{\substack{t \sim T \\ (t, d) = 1}} t \sum_{\substack{e_0 \sim E_0 \\ (e_0, d) = 1}}\, 
    \sum_{\substack{e_1', e_2' \sim E/e_0 \\ (e_1', e_2') = 1 \\ (e_1' e_2', d) = 1}}
