    \sum_{\substack{h_1, h_2 \sim H \\ h_1e_1'\ell_2 \neq h_2e_2'\ell_1}} \beta(e_0e_1', h_1, \ell_1) \, \overline{\beta(e_0e_2', h_2, \ell_2)} 
