\end{aligned}
\]
Note that the inner sum over $n$ can be rewritten as
\[
    \sum_{\substack{n \equiv k\mu \pmod{te_0e_1'e_2'} \\ (n, k) = 1}}
    f_0\left(\frac{n}{N}\right)
    \textnormal{e} \left(\frac{\overline{n}r_0}{k} \right),
