    \sum_{\substack{e_1', e_2' \sim E/e_0 \\ (e_1', e_2') = 1 \\ (e_1' e_2', d) = 1}}
    \sum_{\substack{\ell_1, \ell_2 \sim L \\ \ell_1 \equiv \ell_2 \pmod{te_0} \\ (\ell_1 \ell_2, te_0) = 1 \\ (\ell_1, e_1') = (\ell_2, e_2') = 1}}
