    \sum_{|j| \sim J} \textnormal{e}\left(j \omega\right)\, 
    S\left( (h_1e_1'\ell_2 - h_2e_2'\ell_1)\, \overline{b \ell_1 \ell_2 e_1' e_2'}, j; k's\right)
    \right\vert,
\end{aligned}
\]
where
\[
    \omega = \omega(t, e_0, e_1', e_2', \widehat{\mu}, d, w) := \frac{\widehat{\mu}}{te_0e_1'e_2'} - w \in \mathbf{R}/\mathbf{Z}.
\]
We then let $\ell_0 := (\ell_1, \ell_2)$, $\ell_1' := \ell_1/\ell_0$, $\ell_2' := \ell_2/\ell_0$, and put the variables
\[
    m := h_1e_1'\ell_2' - h_2e_2'\ell_1' \ll \frac{HEL}{E_0 \ell_0}, \qquad\qquad
    r := b \ell_0 \ell_1' \ell_2' e_1' e_2' \asymp x^{O(\eta)} \frac{L^2 E^2}{\ell_0 E_0^2},
\]
and $\ell_0$ into dyadic ranges $m \sim M_{\neq}$, $r \sim R_{\neq}$, $\ell_0 \sim L_0$ to obtain 
\begin{equation} \label{eq:bneq-bound}
    \mathcal{B}_{\neq} \ll_\eta x^{O(\eta)} \sup_{\substack{L_0 \ll L \\ M_{\neq} \ll HEL/(E_0L_0) \\ R_{\neq} \asymp x^{O(\eta)} L^2E^2/(L_0E_0^2)}} |\mathcal{B}_{\neq}'|,
\end{equation}
where
\[
\begin{aligned}
    \mathcal{B}_{\neq}' 
    &:=
    \sum_{t \sim T} \sum_{e_0 \sim E_0}\,
    \sum_{\substack{e_1', e_2' \sim E/e_0 \\ (e_1', e_2') = 1}}\,
    \sum_{\widehat{\mu} \in \mathbf{Z}/te_0e_1'e_2'\mathbf{Z}}
    \\
    &\times 
    \sum_{\substack{r \sim R_{\neq} \\ be_1'e_2' \mid r \\ s \sim S \\ (s, r) = 1 \\ s \mid te_0}}
    \sum_{\substack{\ell_0 \sim L_0 \\ \ell_1', \ell_2' \sim L/\ell_0 \\ (\ell_1', \ell_2') = 1 \\ b\ell_0 \ell_1' \ell_2' e_1' e_2' = r \\ \ell_1' \equiv \ell_2' \pmod{te_0} \\ (\ell_1', e_1') = (\ell_2', e_2') = 1 \\ \mu(\ell_0\ell_1', \ell_0\ell_2') \equiv \widehat{\mu} \\ \pmod{te_0e_1'e_2'}}} 
    \sum_{m \sim M_{\neq}}
    \sum_{\substack{h_1, h_2 \sim H \\ h_1e_1'\ell_2 - h_2e_2'\ell_1 = m}}
    \left\vert 
    \sum_{\substack{k' \\ (k', r) = 1}} g_0 \left(\frac{k'}{K/S}\right)
    \sum_{|j| \sim J} \textnormal{e}\left(j \omega\right)\, 
    S\left(m \overline{r}, j; k's\right)
    \right\vert.
\end{aligned}
\]
As before, once the variables $t, e_0, e_1', e_2', \widehat{\mu}$ are fixed, $\omega$ does not depend on $r, s, m, h_1, h_2, k'$.
We remove the absolute values by inserting $1$-bounded coefficients $\xi_{h_1,h_2}$ (also depending on $t, e_0, e_1', e_2', \widehat{\mu}$ and $r, s, m$), and denote
\[
    a_{m,r,s} = a_{m,r,s}\left(t, e_0, e_1', e_2', \widehat{\mu}\right) := 
    \mathbbm{1}_{b e_1'e_2' \mid r}
    \mathbbm{1}_{s \mid te_0}
    \sum_{\substack{\ell_0 \sim L_0 \\ \ell_1', \ell_2' \sim L/\ell_0 \\ (\ell_1', \ell_2') = 1 \\ b\ell_0 \ell_1' \ell_2' e_1' e_2' = r \\ \ell_1' \equiv \ell_2' \pmod{te_0} \\ (\ell_1', e_1') = (\ell_2', e_2') = 1 \\ \mu(\ell_0\ell_1', \ell_0\ell_2') \equiv \widehat{\mu} \\ \pmod{te_0e_1'e_2'}}}
    \sum_{\substack{h_1, h_2 \sim H \\ h_1e_1'\ell_2' - h_2e_2'\ell_1' = m}} 
    \xi_{h_1, h_2},
\]
to obtain
\begin{equation} \label{eq:bneqprime-bound}
    \mathcal{B}_{\neq}' \ll_\eta x^{O(\eta)} 
    \sum_{t \sim T} \sum_{e_0 \sim E_0}\,
    \sum_{\substack{e_1', e_2' \sim E/e_0 \\ (e_1', e_2') = 1}}\,
    \sum_{\widehat{\mu} \in \mathbf{Z}/te_0e_1'e_2'\mathbf{Z}}
    |\mathcal{K}_{\neq}|,
\end{equation}
where
\[
    \mathcal{K}_{\neq} := \sum_{\substack{r \sim R_{\neq} \\ s \sim S \\ (r, s) = 1}} 
    \sum_{m \sim M_{\neq}} a_m
    \sum_{|j| \sim J} \textnormal{e}(j \omega)
    \sum_{\substack{k' \\ (k', r_{\neq}) = 1}} 
    g_0 \left(\frac{k'}{K/S}\right) S\left(m\overline{r_{\neq}}, j; k's\right).
\]
Now by \cref{thm:di-type-bound}, we have
\[
\begin{aligned}
