    \sum_{\widehat{\mu} \in \mathbf{Z}/(te_0e_1'e_2'\mathbf{Z})} ||a_{m,r,s}||_2
    \\ 
    &\ll 
    \frac{TE^2}{E_0} \sqrt{
    \sum_{t \sim T} \sum_{e_0 \sim E_0}\,
    \sum_{\substack{e_1', e_2' \sim E/e_0 \\ (e_1', e_2') = 1}} \sum_{\substack{s \sim S \\ s \mid te_0}} \sum_{\substack{\ell_0 \sim L_0 \\ \ell_1', \ell_2' \sim L/\ell_0 \\ (\ell_1', \ell_2') = 1 \\ \ell_1' \equiv \ell_2' \pmod{te_0} \\ (\ell_1', e_1') = (\ell_2', e_2') = 1}} 
    \sum_{m \sim M_{\neq}} 
    \left(\sum_{\substack{h_1, h_2 \sim H \\ h_1 e_1' \ell_2' - h_2 e_2' \ell_1' = m}} 1\right)^2
    } 
    \\
    &\ll \frac{TE^2}{E_0} \sqrt{
