    \tau(\ell_1' - \ell_2')^3
    \sum_{m \sim M_{\neq}}
    \sum_{\substack{h_1, h_2 \sim H \\ h_1 e_1' \ell_2' - h_2 e_2' \ell_1' = m}} 
    \sum_{\substack{h_1', h_2' \sim H \\ h_1' e_1' \ell_2' - h_2' e_2' \ell_1' = m}} 1
    }
    \\
    &\ll_\eta
    x^{O(\eta)} \frac{TE^2}{E_0} \sqrt{L_0
    \sum_{m \sim M_{\neq}}\,
    \sum_{\substack{h_1 \sim H \\ e_1' \ll E/E_0 \\ \ell_2' \ll L/L_0 }}
    \sum_{\substack{h_2, e_2', \ell_1' \\ h_2e_2'\ell_1' = h_1 e_1' \ell_2' - m \\ (e_2'\ell_1', e_1'\ell_2') = 1}}
    \ \sum_{\substack{h_1' \sim H \\ h_1'e_1'\ell_2' \equiv m \pmod{e_2'\ell_1'}}} 
