 \label{lem:di-large-sieve}
Given $\varepsilon > 0$, $q \in \mathbf{Z}_+$, $N \gg 1$, a complex sequence $(a_n)_{n \sim N}$, a cusp $\mathfrak{a}$ of $\Gamma_0(q)$, and an associated scaling matrix $\sigma_{\mathfrak{a}}$, one has
\begin{equation} 
    \label{eq:like-di-thm-5}
    \sum_{\substack{j \ge 1 \\ \lambda_{j,q} < 1/4}}
    X^{\theta_{j,q}} 
    \left\vert 
    \sum_{n \sim N} a_n\, \rho_{j,\mathfrak{a}}(n)
    \right\vert^2 
    \ll_\varepsilon 
    (QN)^\varepsilon
    \left(1 + \mu(\mathfrak{a}) N\right) ||a_n||_2^2,
\end{equation}
for any $0 < X \ll \max(1, \mu(\mathfrak{a})^{-1}N^{-1})$.

Moreover, if $(\mathfrak{a}, \sigma_{\mathfrak{a}}) = (\infty, \textnormal{Id})$, then given $Q \gg 1$ and $\alpha \in \mathbf{R}/\mathbf{Z}$, one has
\begin{equation}
